    const { board } = this.gameState;

    for (let i = 0; i < board.length; i++) {
      for (let j = 0; j < board[i].length; j++) {
        if (board[i][j] === null) return true;
      }
    }

    return false;
  }

  isGameOver(): boolean {
    if (!this.hasEmptyCells()) return true;

    const { winner } = this.gameState;

    // Check for horizontal wins
    for (let i = 0; i < this.gameState.board.length; i++) {
      let count = 1;

      for (let j = 1; j < this.gameState.board[i].length; j++) {
        if (this.gameState.board[i][j] === winner) count++;
      }

      if (count >= this.gameState.boardSize) return true;
    }

    // Check for vertical wins
    for (let j = 0; j < this.gameState.board[0].length; j++) {
      let count = 1;

      for (let i = 1; i < this.gameState.board.length; i++) {
        if (this.gameState.board[i][j] === winner) count++;
      }

      if (count >= this.gameState.boardSize) return true;
    }

    // Check for diagonal wins from top-left to bottom-right
    let count = 1;

    for (let i = 1; i < this.gameState.board.length && i < this.gameState.board[0].length; i++) {
      if (this.gameState.board[i][i] === winner) count++;
    }

    if (count >= this.gameState.boardSize) return true;

    // Check for diagonal wins from top-right to bottom-left
