class AiOpponent {
  private lastMove: [number, number];

  constructor() {
    this.reset();
  }

  reset(): void {
    this.lastMove = [-1, -1];
  }

  makeMove(gameEngine: GameEngine): void {
    const { boardSize } = gameEngine.gameState;

    // Prevent making a move if the game is already won or if an AI move was just made
    if (gameEngine.gameState.winner !== null || this.lastMove !== [-1, -1]) return;

    let legalMoves: Array<[number, number]> = [];

    // Get all empty cells in the board
    for (let i = 0; i < boardSize; i++) {
      for (let j = 0; j < boardSize; j++) {
        if (gameEngine.gameState.board[i][j] === null) legalMoves.push([i, j]);
      }
    }

    // Randomly select a move from the legal moves
    const randomIndex = Math.floor(Math.random() * legalMoves.length);
    this.lastMove = legalMoves[randomIndex];
  }
}

