export interface AiOpponentState {
  currentState: GameState;
}

export function getAiOpponentState(): AiOpponentState {
  const currentState: GameState = {
    boardSize: 3,
    currentPlayer: 'O',
    history: [],
    winner: null
  };
  return { currentState };
}

export function runAiOpponent(stateAndEvents: StateAndEvents): void {
  const { currentState } = getAiOpponentState();
  const { actions } = stateAndEvents;

  for (const action of actions) {
    const { row, col } = action;
    if (currentState.history.some(h => h[0] === row && h[1] === col)) continue;

    currentState.history.push([row, col]);
    currentState.board[row][col] = currentState.currentPlayer;
    currentState.currentPlayer = currentState.currentPlayer === 'O' ? 'X' : 'O';
    currentState.winner = checkWin(currentState.board, currentState.currentPlayer);
  }

  // Update Render view with new data
  // Ensure type safety for the output
  // Example: renderView.setData(...);
}

function checkWin(board: number[][], player: 'X' | 'O'): 'X' | 'O' | null {
  for (let i = 0; i < 3; i++) {
    if (board[i][0] === player && board[i][1] === player && board[i][2] === player) return player;
    if (board[0][i] === player && board[1][i] === player && board[2][i] === player) return player;
  }
  if (board[0][0] === player && board[1][1] === player && board[2][2] === player) return player;
  if (board[0][2] === player && board[1][1] === player && board[2][0] === player) return player;
  return null;
}

