        row.style.display = 'flex';
        row.style.flexDirection = 'row';
        row.style.alignItems = 'center';
        row.style.justifyContent = 'center';
        row.style.gap = '10px';
        row.style.width = '100%';
        row.style.height = '100px';
        row.style.fontSize = '2rem';
        row.style.fontWeight = 'bold';
        row.style.color = '#fff';

        for (let j = 0; j < 3; j++) {
            const cell = document.createElement('div');
            cell.style.width = '100px';
            cell.style.height = '100px';
            cell.style.borderRadius = '5px';
            cell.style.border = '1px solid #4a4a6a';
            cell.style.display = 'flex';
            cell.style.alignItems = 'center';
            cell.style.justifyContent = 'center';
            cell.style.fontSize = '1.5rem';
            cell.style.color = '#fff';
            cell.style.userSelect = 'none';

            if (board[i][j] === 1) cell.textContent = 'X';
            else if (board[i][j] === 2) cell.textContent = 'O';

            row.appendChild(cell);
        }

        container.appendChild(row);
    }

    const scoreDisplay = document.createElement('div');
    scoreDisplay.style.textAlign = 'center';
    scoreDisplay.style.marginTop = '20px';
    scoreDisplay.style.fontSize = '1.2rem';

    if (isGameWon) {
        scoreDisplay.textContent = `Player ${winner} wins!`;
    } else if (isGameDrawn) {
        scoreDisplay.textContent = 'It\'s a draw!';
    } else {
        scoreDisplay.textContent = `Player ${currentPlayer}'s turn`;
    }

    container.appendChild(scoreDisplay);

    return container;
}
